CREATE OR REPLACE FUNCTION public.wire_tray_role_blocked() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role = 'tecnico'::public.app_role) AND NOT EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role = 'admin'::public.app_role); $$;
CREATE OR REPLACE FUNCTION public.wire_tray_user_role_blocked(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = _user_id AND ur.role = 'tecnico'::public.app_role) AND NOT EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = _user_id AND ur.role = 'admin'::public.app_role); $$;
CREATE OR REPLACE FUNCTION public.wire_tray_is_global_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ SELECT NOT public.wire_tray_role_blocked() AND EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role = 'admin'::public.app_role); $$;
CREATE OR REPLACE FUNCTION public.wire_tray_has_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ SELECT NOT public.wire_tray_role_blocked() AND EXISTS (SELECT 1 FROM public.user_module_access uma WHERE uma.user_id = auth.uid() AND uma.module_key = 'wire_trays'::public.app_module AND uma.active AND uma.module_role IS NOT NULL); $$;
CREATE OR REPLACE FUNCTION public.wire_tray_current_role() RETURNS public.wire_tray_module_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ SELECT uma.module_role FROM public.user_module_access uma WHERE uma.user_id = auth.uid() AND uma.module_key = 'wire_trays'::public.app_module AND uma.active AND NOT public.wire_tray_role_blocked() LIMIT 1; $$;
CREATE OR REPLACE FUNCTION public.wire_tray_current_role_in(_roles public.wire_tray_module_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ SELECT NOT public.wire_tray_role_blocked() AND EXISTS (SELECT 1 FROM public.user_module_access uma WHERE uma.user_id = auth.uid() AND uma.module_key = 'wire_trays'::public.app_module AND uma.active AND uma.module_role = ANY (_roles)); $$;
CREATE OR REPLACE FUNCTION public.wire_tray_can_view_financials() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ SELECT NOT public.wire_tray_role_blocked() AND EXISTS (SELECT 1 FROM public.user_module_access uma WHERE uma.user_id = auth.uid() AND uma.module_key = 'wire_trays'::public.app_module AND uma.active AND (uma.module_role IN ('admin'::public.wire_tray_module_role, 'comercial'::public.wire_tray_module_role, 'faturamento'::public.wire_tray_module_role) OR (uma.module_role = 'gestor'::public.wire_tray_module_role AND uma.financial_access))); $$;
CREATE OR REPLACE FUNCTION public.wire_tray_assert_role(_roles public.wire_tray_module_role[]) RETURNS public.wire_tray_module_role LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $$ DECLARE v_role public.wire_tray_module_role; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Autenticação obrigatória.' USING ERRCODE = '42501'; END IF; IF public.wire_tray_role_blocked() THEN RAISE EXCEPTION 'Seu perfil de técnico não tem acesso ao módulo Leitos Aramados.' USING ERRCODE = '42501'; END IF; v_role := public.wire_tray_current_role(); IF v_role = ANY (_roles) THEN RETURN v_role; END IF; IF 'admin'::public.wire_tray_module_role = ANY (_roles) AND public.wire_tray_is_global_admin() THEN RETURN 'admin'::public.wire_tray_module_role; END IF; RAISE EXCEPTION 'Seu perfil não permite executar esta operação.' USING ERRCODE = '42501'; END; $$;
CREATE OR REPLACE FUNCTION public.wire_tray_block_technician_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$ BEGIN IF NEW.module_key = 'wire_trays'::public.app_module AND NEW.active AND public.wire_tray_user_role_blocked(NEW.user_id) THEN RAISE EXCEPTION 'Usuários com perfil de técnico não podem receber acesso ao módulo Leitos Aramados.' USING ERRCODE = '42501'; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS wire_tray_block_technician_access ON public.user_module_access;
CREATE TRIGGER wire_tray_block_technician_access BEFORE INSERT OR UPDATE ON public.user_module_access FOR EACH ROW EXECUTE FUNCTION public.wire_tray_block_technician_access();